    # do laço de repetidos - Replace-Once roda primeiro -, e sobram 4 ocorrências para ele.
    @('$msg = "[Invoke-WPFInstall] An Install process is currently running."',
      '$msg = "[Invoke-WPFInstall] Já existe um processo em andamento."'),
